import * as THREE from 'three/webgpu';
import { MeshStandardNodeMaterial, color } from 'three/tsl';
import gsap from 'gsap';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'stat-tile-collection';
  group.position.set(0, -0.19999999999999996, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const timelines = [];
  let meshRoot = null;
  let hoverTL = null;

  // Base placeholder plate while GLB loads (or in case load fails)
  const plateGeo = new THREE.BoxGeometry(1.6, 1.0, 0.08);
  const plateMat = new MeshStandardNodeMaterial();
  plateMat.colorNode = color(new THREE.Color(config?.visual?.colors?.surface || '#0b0b10'));
  plateMat.roughness = 0.55;
  plateMat.metalness = 0.5;
  const plate = new THREE.Mesh(plateGeo, plateMat);
  plate.castShadow = true;
  plate.receiveShadow = true;
  group.add(plate);

  const meshUrl = '/prism-mock/orrery/meshes/gear-a.glb';
  try {
    const gltf = ctx.glbLoader.load(meshUrl);
    if (gltf && gltf.scene) {
      meshRoot = gltf.scene;
      meshRoot.traverse((child) => {
        if (child.isMesh) {
          child.castShadow = true;
          child.receiveShadow = true;
        }
      });
      group.add(meshRoot);
      plate.visible = false;
    }
  } catch (e) {
    // fallback stays visible
  }

  // Metric value + label as MSDF text, sourced from atlas region config
  const valueMesh = createTextMesh({
    text: '—',
    font: 'display',
    weight: 600,
    size: 0.34,
    color: config?.visual?.colors?.paper || '#e8ecf2',
    atlas: ctx.fontAtlas,
    align: 'center',
  });
  valueMesh.position.set(0, 0.15, 0.06);
  group.add(valueMesh);

  const labelMesh = createTextMesh({
    text: 'COLLECTION',
    font: 'text',
    weight: 700,
    size: 0.09,
    color: config?.visual?.colors?.accent || '#ff2a38',
    atlas: ctx.fontAtlas,
    align: 'center',
  });
  labelMesh.position.set(0, -0.1, 0.06);
  group.add(labelMesh);

  // Entrance animation: weighted-settle
  group.scale.set(0.001, 0.001, 0.001);
  const introTL = gsap.timeline();
  introTL.to(group.scale, {
    x: 1.04, y: 1.04, z: 1.04,
    duration: 0.6,
    ease: 'power4.out',
  }).to(group.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.3,
    ease: 'power2.out',
  });
  timelines.push(introTL);

  // Apply cinematic primitives via ctx.primitives — never inline
  if (ctx.primitives['parallax-scroll']) {
    ctx.primitives['parallax-scroll'](group, { intensity: 0.4 });
  }
  if (ctx.primitives['magnetic-cursor']) {
    ctx.primitives['magnetic-cursor'](group, { radius: 1.2, strength: 0.35 });
  }

  // Hover: rise-in subtle
  const baseY = group.position.y;
  const onHoverEnter = () => {
    if (hoverTL) hoverTL.kill();
    hoverTL = gsap.timeline();
    hoverTL.to(group.position, {
      y: baseY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
    timelines.push(hoverTL);
  };
  const onHoverLeave = () => {
    if (hoverTL) hoverTL.kill();
    hoverTL = gsap.timeline();
    hoverTL.to(group.position, {
      y: baseY,
      duration: 0.7,
      ease: 'power3.out',
    });
    timelines.push(hoverTL);
  };

  const onClick = () => {
    if (ctx.emit) {
      ctx.emit('hub-collection.select');
    }
    gsap.timeline()
      .to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' })
      .to(group.scale, { x: 1, y: 1, z: 1, duration: 0.12, ease: 'back.out' });
  };

  group.userData.handlers = {
    hover: onHoverEnter,
    hoverEnter: onHoverEnter,
    hoverLeave: onHoverLeave,
    click: onClick,
  };

  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    if (hoverTL) hoverTL.kill();
    plateGeo.dispose();
    plateMat.dispose();
    if (valueMesh.geometry) valueMesh.geometry.dispose();
    if (valueMesh.material) valueMesh.material.dispose();
    if (labelMesh.geometry) labelMesh.geometry.dispose();
    if (labelMesh.material) labelMesh.material.dispose();
    if (meshRoot) {
      meshRoot.traverse((child) => {
        if (child.isMesh) {
          if (child.geometry) child.geometry.dispose();
          if (child.material) {
            if (Array.isArray(child.material)) {
              child.material.forEach((m) => m.dispose());
            } else {
              child.material.dispose();
            }
          }
        }
      });
    }
  };

  return group;
}
